let html = $json.data; // On récupère le HTML brut du noeud précédent

if (html) {
  // 1. Supprimer les balises <script> et <style> et leur contenu
  html = html.replace(/<script\b[^>]*>([\s\S]*?)<\/script>/gmi, "");
  html = html.replace(/<style\b[^>]*>([\s\S]*?)<\/style>/gmi, "");

  // 2. Supprimer les commentaires HTML
  html = html.replace(/<!--[\s\S]*?-->/g, "");

  // 3. Optionnel : Supprimer les balises SVG (souvent très lourdes en code)
  html = html.replace(/<svg\b[^>]*>([\s\S]*?)<\/svg>/gmi, "");

  // 4. Nettoyer les espaces multiples pour gagner des tokens
  html = html.replace(/\s+/g, ' ').trim();
}

return {
  cleaned_html: html
};

